/**
 * generate-design-tokens.mjs
 *
 * Converts design-tokens.tokens.json → src/styles/design-tokens.css
 *
 * This is the SINGLE source of truth for all design tokens.
 * Run via:  npm run tokens:build
 * Check via: npm run tokens:check   (used in CI — fails if output is stale)
 *
 * ── Color system architecture ──────────────────────────────────────────────
 *
 *  Layer 1 · Primitives  --_p-<palette>-<step>        (INTERNAL)
 *    Raw palette color steps generated by the design tool.
 *    The double-underscore _ prefix is a deliberate convention to
 *    mark these as private. Component CSS must NEVER reference them.
 *
 *  Layer 2 · Color roles  --color-<role>              (PUBLIC)
 *    Semantic aliases that map a role name to a primitive via var().
 *    These are the ONLY color variables component/page CSS should use.
 *    Keeping the role layer separate means:
 *      - Dark mode = reassign roles, touch zero components.
 *      - Brand refresh = update primitives, roles cascade automatically.
 *
 *  Layer 3 · Typography  --type-<scale>-<property>    (PUBLIC)
 *
 *  Layer 4 · Effects     --effect-<name>              (PUBLIC)
 *
 * ──────────────────────────────────────────────────────────────────────────
 */

import { readFile, mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

// ── Paths ──────────────────────────────────────────────────────────────────

const repositoryRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const sourcePath = path.join(repositoryRoot, "design-tokens.tokens.json");
const outputPath = path.join(repositoryRoot, "src", "styles", "design-tokens.css");

// ── Helpers ────────────────────────────────────────────────────────────────

/** "Primary Container" → "primary-container" */
function toKebabCase(value) {
  return value
    .trim()
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .toLowerCase();
}

function requireObject(value, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} must be a plain object, got ${typeof value}.`);
  }
  return value;
}

/**
 * Normalise Figma 8-digit hex (#rrggbbff → #rrggbb, or rgba() for transparency).
 * Leaves 6-digit hex and other values untouched.
 */
function normaliseColor(value) {
  if (typeof value !== "string") return value;
  const m = value.match(/^#([0-9a-f]{6})([0-9a-f]{2})$/i);
  if (!m) return value;
  const alpha = m[2].toLowerCase();
  if (alpha === "ff") return `#${m[1]}`;
  const a = parseInt(alpha, 16);
  const r = parseInt(m[1].slice(0, 2), 16);
  const g = parseInt(m[1].slice(2, 4), 16);
  const b = parseInt(m[1].slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${+(a / 255).toFixed(3)})`;
}

// ── Layer 1: Primitive variables ───────────────────────────────────────────
//  Naming: --_p-<palette>-<step>
//  e.g.    --_p-primary-40, --_p-neutral-variant-90

/**
 * Build the CSS variable name for a primitive color.
 *
 * @param {string[]} tokenPath  e.g. ["primitives", "color palettes", "primary", "primary40"]
 * @returns {string}  e.g. "--_p-primary-40"
 */
function primitiveVarName(tokenPath) {
  const [, group, family, tokenName] = tokenPath;

  if (group === "key colors" && family && !tokenName) {
    // e.g. ["primitives", "key colors", "primary key color"]
    const name = toKebabCase(family.replace(/ key color$/, ""));
    return `--_p-key-${name}`;
  }

  if (group === "color palettes" && family && tokenName) {
    // e.g. ["primitives", "color palettes", "neutral variant", "neutral variant90"]
    const paletteSlug = toKebabCase(family); // "neutral-variant"
    const num = tokenName.match(/(\d+)$/)?.[1];
    if (!num) {
      throw new Error(`Cannot extract step number from token "${tokenName}".`);
    }
    return `--_p-${paletteSlug}-${num}`;
  }

  throw new Error(`Unsupported primitive colour path: ${tokenPath.join(".")}`);
}

/** Recursively collect all { type: "color" } tokens in an object tree. */
function collectColorTokens(node, pathSegments, tokens = []) {
  for (const [name, value] of Object.entries(
    requireObject(node, pathSegments.join(".")),
  )) {
    const tokenPath = [...pathSegments, name];
    if (value?.type === "color" && typeof value.value === "string") {
      tokens.push({ path: tokenPath, value: value.value });
      continue;
    }
    if (value && typeof value === "object" && !Array.isArray(value)) {
      collectColorTokens(value, tokenPath, tokens);
    }
  }
  return tokens;
}

/**
 * Build primitive declarations and a lookup map for alias resolution.
 *
 * @returns {{ declarations: string[], aliasMap: Map<string, string> }}
 *   aliasMap: dotted token path → CSS variable name
 */
function buildPrimitiveLayer(primitives) {
  const tokens = collectColorTokens(primitives, ["primitives"]);
  const aliasMap = new Map();
  const declarations = [];

  for (const { path: tokenPath, value } of tokens) {
    const cssVar = primitiveVarName(tokenPath);
    aliasMap.set(tokenPath.join("."), cssVar);
    declarations.push(`  ${cssVar}: ${normaliseColor(value)};`);
  }

  return { declarations, aliasMap };
}

// ── Layer 2: Color role variables ──────────────────────────────────────────
//  Naming: --color-<role>
//  Values: var(--_p-...) so primitives remain the single source of truth.

/**
 * Resolve a Figma alias string like "{primitives.color palettes.primary.primary40}"
 * to a CSS var() reference using the aliasMap.
 */
function resolveAlias(alias, aliasMap, roleLabel) {
  const inner = alias.replace(/^\{|\}$/g, "");
  const cssVar = aliasMap.get(inner);
  if (!cssVar) {
    throw new Error(
      `Color role "${roleLabel}" references unknown primitive "${inner}". ` +
        `Known paths: ${[...aliasMap.keys()].slice(0, 5).join(", ")} …`,
    );
  }
  return `var(${cssVar})`;
}

function buildColorRoleLayer(colorRoles, aliasMap) {
  const declarations = [];

  for (const [name, token] of Object.entries(
    requireObject(colorRoles, "color roles"),
  )) {
    requireObject(token, `color roles.${name}`);
    if (token.type !== "color" || typeof token.value !== "string") {
      throw new TypeError(`color roles.${name} must be a color token.`);
    }

    const cssVar = `--color-${toKebabCase(name)}`;
    let cssValue = token.value;

    if (cssValue.startsWith("{")) {
      cssValue = resolveAlias(cssValue, aliasMap, name);
    } else {
      cssValue = normaliseColor(cssValue);
    }

    declarations.push(`  ${cssVar}: ${cssValue};`);
  }

  return declarations;
}

// ── Layer 3: Typography variables ─────────────────────────────────────────
//  Naming: --type-<scale>-<property>
//  e.g.   --type-display-large-font-size, --type-body-medium-line-height

function formatTypographyValue(token, label) {
  requireObject(token, label);

  if (token.type === "dimension") {
    if (typeof token.value !== "number" || !Number.isFinite(token.value)) {
      throw new TypeError(`${label} must be a finite number.`);
    }
    return `${token.value}px`;
  }

  if (token.type === "number") {
    if (typeof token.value !== "number" || !Number.isFinite(token.value)) {
      throw new TypeError(`${label} must be a finite number.`);
    }
    return String(token.value);
  }

  if (token.type === "string" && typeof token.value === "string") {
    if (label.endsWith(".fontFamily")) {
      return `"${token.value.replaceAll('"', '\\"')}", sans-serif`;
    }
    return token.value;
  }

  throw new TypeError(
    `${label} has unsupported type ${JSON.stringify(token.type)}.`,
  );
}

function buildTypographyLayer(typography) {
  const declarations = [];

  for (const [styleName, properties] of Object.entries(
    requireObject(typography, "typography"),
  )) {
    for (const [propertyName, token] of Object.entries(
      requireObject(properties, `typography.${styleName}`),
    )) {
      const label = `typography.${styleName}.${propertyName}`;
      const cssVar = `--type-${toKebabCase(styleName)}-${toKebabCase(propertyName)}`;
      declarations.push(`  ${cssVar}: ${formatTypographyValue(token, label)};`);
    }
  }

  return declarations;
}

// ── Layer 4: Effect (shadow) variables ─────────────────────────────────────
//  Naming: --effect-<name>

function buildEffectLayer(effects) {
  const declarations = [];

  for (const [name, token] of Object.entries(
    requireObject(effects, "effect"),
  )) {
    requireObject(token, `effect.${name}`);
    const value = requireObject(token.value, `effect.${name}.value`);

    if (token.type !== "custom-shadow" || value.shadowType !== "dropShadow") {
      throw new TypeError(`effect.${name} must be a drop-shadow token.`);
    }

    const spread = typeof value.spread === "number" && value.spread !== 0
      ? ` ${value.spread}px`
      : "";
    const shadow = `${value.offsetX}px ${value.offsetY}px ${value.radius}px${spread} ${normaliseColor(value.color)}`;
    const cssVar = `--effect-${toKebabCase(name)}`;
    declarations.push(`  ${cssVar}: ${shadow};`);
  }

  return declarations;
}

// ── Assemble CSS ───────────────────────────────────────────────────────────

function section(title, declarations) {
  return [
    `\n  /* ── ${title} ── */`,
    ...declarations,
  ].join("\n");
}

function generateCss(tokens) {
  const primitives = requireObject(tokens.primitives, "primitives");
  const { declarations: primitiveDeclarations, aliasMap } =
    buildPrimitiveLayer(primitives);

  const roleDeclarations = buildColorRoleLayer(tokens["color roles"], aliasMap);
  const typographyDeclarations = buildTypographyLayer(tokens.typography);
  const effectDeclarations = buildEffectLayer(tokens.effect);

  const timestamp = new Date().toISOString();

  return [
    "/**",
    " * design-tokens.css — AUTO-GENERATED. DO NOT EDIT MANUALLY.",
    " *",
    " * Source of truth : design-tokens.tokens.json",
    " * Regenerate      : npm run tokens:build",
    " * Check (CI)      : npm run tokens:check",
    " *",
    " * Variable conventions",
    " * ──────────────────────────────────────────────────────────",
    " *  --_p-*       Primitive palette steps     INTERNAL — do not use in component CSS",
    " *  --color-*    Semantic color roles         PUBLIC — use these in all component CSS",
    " *  --type-*     Typography scale tokens      PUBLIC",
    " *  --effect-*   Shadow / elevation tokens    PUBLIC",
    " *",
    " * Color system design",
    " * ──────────────────────────────────────────────────────────",
    " *  Primitives are raw palette values (hue × lightness steps).",
    " *  Color roles are semantic names for those values.",
    " *  UI code uses only --color-* so that themes, dark mode, or",
    " *  brand changes are made by reassigning roles — not hunting",
    " *  through every component.",
    ` *`,
    ` * Generated: ${timestamp}`,
    " */",
    "",
    ":root {",
    section(
      "LAYER 1 · PRIMITIVE COLORS — internal, do not use in component CSS",
      primitiveDeclarations,
    ),
    section(
      "LAYER 2 · COLOR ROLES — use these in all component and page CSS",
      roleDeclarations,
    ),
    section("LAYER 3 · TYPOGRAPHY", typographyDeclarations),
    section("LAYER 4 · EFFECTS / SHADOWS", effectDeclarations),
    "}",
    "",
  ].join("\n");
}

// ── Entry point ────────────────────────────────────────────────────────────

const source = JSON.parse(await readFile(sourcePath, "utf8"));
const generatedCss = generateCss(source);

if (process.argv.includes("--check")) {
  // In CI: fail if the committed file is out of date.
  const currentCss = await readFile(outputPath, "utf8").catch(() => "");
  // Strip the timestamp line before comparing so CI isn't always stale.
  const stripTimestamp = (s) => s.replace(/ \* Generated: .+/g, " * Generated: <timestamp>");
  if (stripTimestamp(currentCss) !== stripTimestamp(generatedCss)) {
    throw new Error(
      "Generated design tokens are stale. Run `npm run tokens:build` and commit the result.",
    );
  }
  console.log("Generated design tokens are current.");
} else {
  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, generatedCss, "utf8");
  console.log(`Generated ${path.relative(repositoryRoot, outputPath)}.`);
}
